import factsJson from './facts.json';

// facts.json is GENERATED by scripts/utils/portfolio-facts.py in the d-context workspace,
// never edited by hand: every figure the site shows (tests, versions, tenants, the app
// census, the platform page's nodes, guests, backups, probes and pipelines) is measured
// there. A test fails the CI build when the file is older than 120 days, so a stale figure
// is a red build instead of a quiet lie.

export interface ProjectTests {
  total: number;
  backend?: number;
  frontend?: number;
  e2e?: number;
  packages?: number;
}

export interface ProjectVersions {
  react?: number;
  typescript?: number;
  node?: number;
  express?: number;
  vite?: number;
  tailwind?: number;
  mongodb?: number;
}

export interface ProjectFacts {
  tests: ProjectTests;
  versions: ProjectVersions;
  ci: string;
  /** dcompany only: MCP tool definitions counted in its control-plane source. */
  mcpTools?: number;
}

/** The platform page's figures, read from Prometheus and the CI checkouts on generation day. */
export interface PlatformFacts {
  /** Proxmox cluster nodes. */
  nodes: number;
  /** Running guests by kind; templates are not counted. */
  guests: { lxc: number; vm: number };
  /** ZFS replication jobs between nodes. */
  replicationJobs: number;
  /** Guests outside every backup job — the figure that should stay at zero. */
  guestsWithoutBackup: number;
  /** Proxmox Backup Server datastores and the bytes they hold (deduplicated). */
  backup: { datastores: number; usedBytes: number };
  /** Prometheus scrape targets, jobs, blackbox probes and alerting rules. */
  monitoring: { targets: number; jobs: number; probes: number; alertRules: number };
  /** Workflow files across the repos with a pipeline, and how many forges run them. */
  ci: { workflows: number; repos: number; forges: number };
}

export interface Facts {
  generatedAt: string;
  testsMeasuredAt: string;
  apps: { production: number; public: number };
  tests: { total: number };
  dauthTenants: number;
  saasSince: string;
  projects: Record<string, ProjectFacts>;
  platform: PlatformFacts;
}

export const facts: Facts = factsJson;

/**
 * Thousands separator by UI language: 87021 → "87.021" (es) / "87,021" (en).
 * Deliberately not Intl: the es-ES CLDR rule leaves four-digit numbers ungrouped
 * ("3170"), and the site has always grouped them ("3.170").
 */
export function formatInt(n: number, lang: string): string {
  const separator = lang.startsWith('es') ? '.' : ',';
  return String(Math.trunc(n)).replace(/\B(?=(\d{3})+(?!\d))/g, separator);
}

export function roundDownToThousand(n: number): number {
  return Math.floor(n / 1000) * 1000;
}

export function roundDownToTen(n: number): number {
  return Math.floor(n / 10) * 10;
}

/** Fixed decimals with the language's separator: 2.787 → "2,8" (es) / "2.8" (en). */
export function formatDecimal(n: number, lang: string, digits = 1): string {
  const fixed = n.toFixed(digits);
  return lang.startsWith('es') ? fixed.replace('.', ',') : fixed;
}

/** Long date in the UI language: "14 de octubre de 2026" / "14 October 2026". */
export function formatDate(isoDate: string, lang: string): string {
  // A date-only ISO string parses as UTC midnight; formatting in UTC keeps the day it names.
  return new Date(isoDate).toLocaleDateString(lang.startsWith('es') ? 'es-ES' : 'en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC',
  });
}

const TB = 1e12;

const DAY_MS = 86_400_000;

/** Age of an ISO date in days — what the CI staleness test compares against its limit. */
export function ageInDays(isoDate: string, now: Date = new Date()): number {
  return (now.getTime() - new Date(isoDate).getTime()) / DAY_MS;
}

/** Whole years elapsed since an ISO date — the "years in SaaS" figure, never typed. */
export function yearsSince(isoDate: string, now: Date = new Date()): number {
  const since = new Date(isoDate);
  let years = now.getFullYear() - since.getFullYear();
  const beforeAnniversary =
    now.getMonth() < since.getMonth() ||
    (now.getMonth() === since.getMonth() && now.getDate() < since.getDate());
  if (beforeAnniversary) years -= 1;
  return Math.max(0, years);
}

/**
 * Interpolation values for a project's translated copy: `{{tests}}`, `{{backend}}`,
 * `{{frontend}}`, `{{e2e}}`, `{{packages}}`, `{{tenants}}` and, where measured,
 * `{{mcpTools}}` (floored to the ten, for a "more than N" sentence), already formatted
 * for the language, so the locale strings carry no digits of their own.
 */
export function projectVars(slug: string, lang: string): Record<string, string> {
  const vars: Record<string, string> = { tenants: String(facts.dauthTenants) };
  const project = facts.projects[slug];
  if (!project) return vars;
  for (const [group, count] of Object.entries(project.tests)) {
    vars[group === 'total' ? 'tests' : group] = formatInt(count, lang);
  }
  if (project.mcpTools !== undefined) {
    vars.mcpTools = formatInt(roundDownToTen(project.mcpTools), lang);
  }
  return vars;
}

/**
 * Interpolation values for the platform page: every measured figure formatted for the
 * language (`{{nodes}}`, `{{guests}}`, `{{probes}}`…), the backup usage as `{{backupTb}}`
 * with one decimal, and `{{measuredAt}}`, the day the file was generated, as a long date.
 */
export function platformVars(lang: string): Record<string, string> {
  const p = facts.platform;
  return {
    nodes: formatInt(p.nodes, lang),
    lxc: formatInt(p.guests.lxc, lang),
    vms: formatInt(p.guests.vm, lang),
    guests: formatInt(p.guests.lxc + p.guests.vm, lang),
    replicationJobs: formatInt(p.replicationJobs, lang),
    guestsWithoutBackup: formatInt(p.guestsWithoutBackup, lang),
    datastores: formatInt(p.backup.datastores, lang),
    backupTb: formatDecimal(p.backup.usedBytes / TB, lang),
    targets: formatInt(p.monitoring.targets, lang),
    jobs: formatInt(p.monitoring.jobs, lang),
    probes: formatInt(p.monitoring.probes, lang),
    alertRules: formatInt(p.monitoring.alertRules, lang),
    workflows: formatInt(p.ci.workflows, lang),
    repos: formatInt(p.ci.repos, lang),
    forges: formatInt(p.ci.forges, lang),
    measuredAt: formatDate(facts.generatedAt, lang),
  };
}
